```python
# fireworks_glm52_fast_client.py
#
# Fireworks documents the chat-completions endpoint at
#  [page:1]
#
# Fireworks documents temperature in the 0..2 range, max_tokens as the maximum
# generated-token budget, and reasoning_effort with a supported "max" value [page:1]
#
# Fireworks lists the GLM 5.2 model path as accounts/fireworks/models/glm-5p2 and
# its context length as 1040k tokens on the model page [page:2]

from __future__ import annotations

import argparse
import json
import os
import sys
import time
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Dict, List, Optional, Sequence

import requests


API_BASE_URL = os.getenv("FIREWORKS_API_BASE_URL", "")
CHAT_COMPLETIONS_PATH = "/v1/chat/completions"
DEFAULT_MODEL = os.getenv("FIREWORKS_MODEL", "accounts/fireworks/models/glm-5p2")
DEFAULT_TEMPERATURE = 0.1
DEFAULT_MAX_TOKENS = 128000
DEFAULT_REASONING_EFFORT = "max"
DEFAULT_TIMEOUT_SECONDS = 600
DEFAULT_MAX_RETRIES = 6
DEFAULT_BACKOFF_SECONDS = 1.0
DEFAULT_CONTEXT_BEHAVIOR = "truncate"
USER_AGENT = "fireworks-glm52-fast-client/1.0"


@dataclass(frozen=True)
class Config:
    api_key: str
    model: str
    temperature: float
    max_tokens: int
    reasoning_effort: str
    timeout_seconds: int
    max_retries: int
    backoff_seconds: float
    context_length_exceeded_behavior: str
    system_prompt: Optional[str]
    user_prompt: str
    output_file: Optional[Path]
    raw_output_file: Optional[Path]
    show_reasoning: bool
    show_usage: bool
    prompt_cache_key: Optional[str]
    prompt_cache_isolation_key: Optional[str]
    user_id: Optional[str]
    safe_tokenization: Optional[bool]
    prompt_truncate_len: Optional[int]
    perf_metrics_in_response: bool
    metadata: Optional[Dict[str, str]]
    seed: Optional[int]


class FireworksError(RuntimeError):
    pass


def parse_args(argv: Optional[Sequence[str]] = None) -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description="Production-ready Fireworks GLM 5.2 client for large-context reasoning calls."
    )

    prompt_source = parser.add_mutually_exclusive_group(required=False)
    prompt_source.add_argument(
        "--prompt",
        type=str,
        help="User prompt text. If omitted, the client reads stdin when available.",
    )
    prompt_source.add_argument(
        "--prompt-file",
        type=Path,
        help="Path to a UTF-8 text file containing the user prompt.",
    )

    parser.add_argument(
        "--system-prompt",
        type=str,
        default=os.getenv("SYSTEM_PROMPT"),
        help="Optional system prompt text.",
    )
    parser.add_argument(
        "--system-prompt-file",
        type=Path,
        help="Path to a UTF-8 text file containing the system prompt.",
    )
    parser.add_argument(
        "--model",
        type=str,
        default=DEFAULT_MODEL,
        help=f'Fireworks model name. Default: "{DEFAULT_MODEL}"',
    )
    parser.add_argument(
        "--temperature",
        type=float,
        default=float(os.getenv("FIREWORKS_TEMPERATURE", DEFAULT_TEMPERATURE)),
        help=f"Sampling temperature. Default: {DEFAULT_TEMPERATURE}",
    )
    parser.add_argument(
        "--max-tokens",
        type=int,
        default=int(os.getenv("FIREWORKS_MAX_TOKENS", DEFAULT_MAX_TOKENS)),
        help=f"Maximum generated tokens. Default: {DEFAULT_MAX_TOKENS}",
    )
    parser.add_argument(
        "--reasoning-effort",
        type=str,
        default=os.getenv("FIREWORKS_REASONING_EFFORT", DEFAULT_REASONING_EFFORT),
        choices=["low", "medium", "high", "xhigh", "max", "none", "adaptive"],
        help=f'Reasoning effort. Default: "{DEFAULT_REASONING_EFFORT}"',
    )
    parser.add_argument(
        "--timeout-seconds",
        type=int,
        default=int(os.getenv("FIREWORKS_TIMEOUT_SECONDS", DEFAULT_TIMEOUT_SECONDS)),
        help=f"HTTP timeout in seconds. Default: {DEFAULT_TIMEOUT_SECONDS}",
    )
    parser.add_argument(
        "--max-retries",
        type=int,
        default=int(os.getenv("FIREWORKS_MAX_RETRIES", DEFAULT_MAX_RETRIES)),
        help=f"Max retry attempts for retryable errors. Default: {DEFAULT_MAX_RETRIES}",
    )
    parser.add_argument(
        "--backoff-seconds",
        type=float,
        default=float(os.getenv("FIREWORKS_BACKOFF_SECONDS", DEFAULT_BACKOFF_SECONDS)),
        help=f"Base exponential backoff in seconds. Default: {DEFAULT_BACKOFF_SECONDS}",
    )
    parser.add_argument(
        "--context-length-exceeded-behavior",
        type=str,
        default=os.getenv(
            "FIREWORKS_CONTEXT_LENGTH_EXCEEDED_BEHAVIOR",
            DEFAULT_CONTEXT_BEHAVIOR,
        ),
        choices=["truncate", "error"],
        help=f'Context overflow handling. Default: "{DEFAULT_CONTEXT_BEHAVIOR}"',
    )
    parser.add_argument(
        "--output-file",
        type=Path,
        help="Optional path to write final assistant text.",
    )
    parser.add_argument(
        "--raw-output-file",
        type=Path,
        help="Optional path to write the full JSON response.",
    )
    parser.add_argument(
        "--show-reasoning",
        action="store_true",
        help="Print reasoning_content to stderr when present.",
    )
    parser.add_argument(
        "--show-usage",
        action="store_true",
        help="Print usage and perf metrics to stderr when present.",
    )
    parser.add_argument(
        "--prompt-cache-key",
        type=str,
        default=os.getenv("FIREWORKS_PROMPT_CACHE_KEY"),
        help="Optional Fireworks prompt cache key.",
    )
    parser.add_argument(
        "--prompt-cache-isolation-key",
        type=str,
        default=os.getenv("FIREWORKS_PROMPT_CACHE_ISOLATION_KEY"),
        help="Optional Fireworks prompt cache isolation key.",
    )
    parser.add_argument(
        "--user-id",
        type=str,
        default=os.getenv("FIREWORKS_USER_ID"),
        help="Optional end-user identifier.",
    )
    parser.add_argument(
        "--safe-tokenization",
        dest="safe_tokenization",
        action="store_true",
        help="Explicitly enable safe tokenization.",
    )
    parser.add_argument(
        "--no-safe-tokenization",
        dest="safe_tokenization",
        action="store_false",
        help="Explicitly disable safe tokenization.",
    )
    parser.set_defaults(safe_tokenization=None)
    parser.add_argument(
        "--prompt-truncate-len",
        type=int,
        default=None,
        help="Optional server-side prompt truncation length in tokens.",
    )
    parser.add_argument(
        "--perf-metrics-in-response",
        action="store_true",
        help="Request perf metrics in the response body.",
    )
    parser.add_argument(
        "--metadata-json",
        type=str,
        default=None,
        help='Optional JSON object string, for example: \'{"env":"prod","job":"batch-7"}\'',
    )
    parser.add_argument(
        "--seed",
        type=int,
        default=None,
        help="Optional seed for deterministic sampling.",
    )

    return parser.parse_args(argv)


def read_text_file(path: Path) -> str:
    try:
        return path.read_text(encoding="utf-8")
    except FileNotFoundError as exc:
        raise FireworksError(f"File not found: {path}") from exc
    except OSError as exc:
        raise FireworksError(f"Unable to read file: {path}") from exc


def resolve_prompt(args: argparse.Namespace) -> str:
    if args.prompt is not None:
        prompt = args.prompt
    elif args.prompt_file is not None:
        prompt = read_text_file(args.prompt_file)
    elif not sys.stdin.isatty():
        prompt = sys.stdin.read()
    else:
        raise FireworksError(
            "No user prompt provided. Use --prompt, --prompt-file, or pipe text on stdin."
        )

    prompt = prompt.strip()
    if not prompt:
        raise FireworksError("User prompt is empty.")
    return prompt


def resolve_system_prompt(args: argparse.Namespace) -> Optional[str]:
    if args.system_prompt_file is not None:
        value = read_text_file(args.system_prompt_file).strip()
        return value or None
    if args.system_prompt is None:
        return None
    value = args.system_prompt.strip()
    return value or None


def parse_metadata(raw: Optional[str]) -> Optional[Dict[str, str]]:
    if raw is None:
        return None

    try:
        parsed = json.loads(raw)
    except json.JSONDecodeError as exc:
        raise FireworksError(f"Invalid --metadata-json: {exc}") from exc

    if not isinstance(parsed, dict):
        raise FireworksError("--metadata-json must decode to a JSON object.")

    normalized: Dict[str, str] = {}
    for key, value in parsed.items():
        if not isinstance(key, str):
            raise FireworksError("All metadata keys must be strings.")
        if not isinstance(value, str):
            normalized[key] = json.dumps(value, ensure_ascii=False)
        else:
            normalized[key] = value
    return normalized


def validate_args(args: argparse.Namespace) -> None:
    if not (0.0 <= args.temperature <= 2.0):
        raise FireworksError("--temperature must be between 0 and 2.")
    if args.max_tokens <= 0:
        raise FireworksError("--max-tokens must be a positive integer.")
    if args.timeout_seconds <= 0:
        raise FireworksError("--timeout-seconds must be a positive integer.")
    if args.max_retries < 0:
        raise FireworksError("--max-retries cannot be negative.")
    if args.backoff_seconds < 0:
        raise FireworksError("--backoff-seconds cannot be negative.")
    if args.prompt_truncate_len is not None and args.prompt_truncate_len <= 0:
        raise FireworksError("--prompt-truncate-len must be positive when provided.")


def build_config(args: argparse.Namespace) -> Config:
    api_key = os.getenv("FIREWORKS_API_KEY", "").strip()
    if not api_key:
        raise FireworksError("Environment variable FIREWORKS_API_KEY is required.")

    return Config(
        api_key=api_key,
        model=args.model.strip(),
        temperature=args.temperature,
        max_tokens=args.max_tokens,
        reasoning_effort=args.reasoning_effort,
        timeout_seconds=args.timeout_seconds,
        max_retries=args.max_retries,
        backoff_seconds=args.backoff_seconds,
        context_length_exceeded_behavior=args.context_length_exceeded_behavior,
        system_prompt=resolve_system_prompt(args),
        user_prompt=resolve_prompt(args),
        output_file=args.output_file,
        raw_output_file=args.raw_output_file,
        show_reasoning=args.show_reasoning,
        show_usage=args.show_usage,
        prompt_cache_key=args.prompt_cache_key,
        prompt_cache_isolation_key=args.prompt_cache_isolation_key,
        user_id=args.user_id,
        safe_tokenization=args.safe_tokenization,
        prompt_truncate_len=args.prompt_truncate_len,
        perf_metrics_in_response=args.perf_metrics_in_response,
        metadata=parse_metadata(args.metadata_json),
        seed=args.seed,
    )


def build_messages(system_prompt: Optional[str], user_prompt: str) -> List[Dict[str, str]]:
    messages: List[Dict[str, str]] = []
    if system_prompt:
        messages.append({"role": "system", "content": system_prompt})
    messages.append({"role": "user", "content": user_prompt})
    return messages


def build_payload(config: Config) -> Dict[str, Any]:
    payload: Dict[str, Any] = {
        "model": config.model,
        "messages": build_messages(config.system_prompt, config.user_prompt),
        "temperature": config.temperature,
        "max_tokens": config.max_tokens,
        "reasoning_effort": config.reasoning_effort,
        "stream": False,
        "context_length_exceeded_behavior": config.context_length_exceeded_behavior,
    }

    if config.prompt_cache_key:
        payload["prompt_cache_key"] = config.prompt_cache_key
    if config.prompt_cache_isolation_key:
        payload["prompt_cache_isolation_key"] = config.prompt_cache_isolation_key
    if config.user_id:
        payload["user"] = config.user_id
    if config.safe_tokenization is not None:
        payload["safe_tokenization"] = config.safe_tokenization
    if config.prompt_truncate_len is not None:
        payload["prompt_truncate_len"] = config.prompt_truncate_len
    if config.perf_metrics_in_response:
        payload["perf_metrics_in_response"] = True
    if config.metadata is not None:
        payload["metadata"] = config.metadata
    if config.seed is not None:
        payload["seed"] = config.seed

    return payload


def build_headers(api_key: str) -> Dict[str, str]:
    return {
        "Authorization": f"Bearer {api_key}",
        "Content-Type": "application/json",
        "Accept": "application/json",
        "User-Agent": USER_AGENT,
    }


def is_retryable_status(status_code: int) -> bool:
    return status_code == 429 or 500 <= status_code < 600


def get_retry_delay(response: Optional[requests.Response], attempt: int, base_backoff: float) -> float:
    if response is not None:
        retry_after = response.headers.get("Retry-After")
        if retry_after:
            try:
                value = float(retry_after)
                return max(value, 0.0)
            except ValueError:
                pass
    return base_backoff * (2 ** attempt)


def request_chat_completion(config: Config) -> Dict[str, Any]:
    url = f"{API_BASE_URL.rstrip('/')}{CHAT_COMPLETIONS_PATH}"
    headers = build_headers(config.api_key)
    payload = build_payload(config)

    session = requests.Session()
    last_error: Optional[BaseException] = None
    last_response_text = ""

    for attempt in range(config.max_retries + 1):
        response: Optional[requests.Response] = None
        try:
            response = session.post(
                url,
                headers=headers,
                json=payload,
                timeout=config.timeout_seconds,
            )

            if is_retryable_status(response.status_code) and attempt < config.max_retries:
                delay = get_retry_delay(response, attempt, config.backoff_seconds)
                time.sleep(delay)
                continue

            if response.status_code >= 400:
                last_response_text = safe_response_text(response)
                raise FireworksError(
                    f"Fireworks API error {response.status_code}: {last_response_text}"
                )

            try:
                return response.json()
            except json.JSONDecodeError as exc:
                last_response_text = safe_response_text(response)
                raise FireworksError(
                    f"Fireworks returned non-JSON content: {last_response_text}"
                ) from exc

        except (requests.Timeout, requests.ConnectionError) as exc:
            last_error = exc
            if attempt < config.max_retries:
                delay = get_retry_delay(response, attempt, config.backoff_seconds)
                time.sleep(delay)
                continue
            raise FireworksError(f"Request failed after retries: {exc}") from exc

        except requests.RequestException as exc:
            last_error = exc
            raise FireworksError(f"Unexpected HTTP client error: {exc}") from exc

    if last_error is not None:
        raise FireworksError(f"Request failed after retries: {last_error}")
    raise FireworksError(f"Request failed after retries. Last response: {last_response_text}")


def safe_response_text(response: requests.Response, limit: int = 4000) -> str:
    try:
        text = response.text
    except Exception:
        text = "<unreadable response body>"
    if len(text) > limit:
        return text[:limit]
    return text


def extract_choice(response_json: Dict[str, Any]) -> Dict[str, Any]:
    choices = response_json.get("choices")
    if not isinstance(choices, list) or not choices:
        raise FireworksError("Response does not contain choices[0].")
    choice = choices[0]
    if not isinstance(choice, dict):
        raise FireworksError("Response choice is not an object.")
    return choice


def extract_message(choice: Dict[str, Any]) -> Dict[str, Any]:
    message = choice.get("message")
    if not isinstance(message, dict):
        raise FireworksError("Response choice does not contain a message object.")
    return message


def extract_text(message: Dict[str, Any]) -> str:
    content = message.get("content", "")
    if content is None:
        return ""
    if isinstance(content, str):
        return content
    if isinstance(content, list):
        parts: List[str] = []
        for item in content:
            if isinstance(item, dict) and item.get("type") == "text":
                text = item.get("text")
                if isinstance(text, str):
                    parts.append(text)
        return "".join(parts)
    return str(content)


def extract_reasoning(message: Dict[str, Any]) -> str:
    reasoning = message.get("reasoning_content", "")
    if reasoning is None:
        return ""
    if isinstance(reasoning, str):
        return reasoning
    if isinstance(reasoning, list):
        parts: List[str] = []
        for item in reasoning:
            if isinstance(item, dict):
                text = item.get("text")
                if isinstance(text, str):
                    parts.append(text)
        return "".join(parts)
    return str(reasoning)


def write_text_file(path: Path, text: str) -> None:
    try:
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(text, encoding="utf-8")
    except OSError as exc:
        raise FireworksError(f"Unable to write file: {path}") from exc


def write_json_file(path: Path, payload: Dict[str, Any]) -> None:
    try:
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")
    except OSError as exc:
        raise FireworksError(f"Unable to write JSON file: {path}") from exc


def print_usage_and_metrics(response_json: Dict[str, Any]) -> None:
    usage = response_json.get("usage")
    perf_metrics = response_json.get("perf_metrics")

    if usage is not None:
        sys.stderr.write("=== usage ===\n")
        sys.stderr.write(json.dumps(usage, ensure_ascii=False, indent=2))
        sys.stderr.write("\n")

    if perf_metrics is not None:
        sys.stderr.write("=== perf_metrics ===\n")
        sys.stderr.write(json.dumps(perf_metrics, ensure_ascii=False, indent=2))
        sys.stderr.write("\n")


def main(argv: Optional[Sequence[str]] = None) -> int:
    try:
        args = parse_args(argv)
        validate_args(args)
        config = build_config(args)
        response_json = request_chat_completion(config)

        if config.raw_output_file is not None:
            write_json_file(config.raw_output_file, response_json)

        choice = extract_choice(response_json)
        message = extract_message(choice)
        final_text = extract_text(message)
        reasoning_text = extract_reasoning(message)

        if config.output_file is not None:
            write_text_file(config.output_file, final_text)

        if config.show_reasoning and reasoning_text:
            sys.stderr.write("=== reasoning_content ===\n")
            sys.stderr.write(reasoning_text)
            if not reasoning_text.endswith("\n"):
                sys.stderr.write("\n")

        if config.show_usage:
            print_usage_and_metrics(response_json)

        sys.stdout.write(final_text)
        if final_text and not final_text.endswith("\n"):
            sys.stdout.write("\n")
        sys.stdout.flush()
        return 0

    except KeyboardInterrupt:
        sys.stderr.write("Interrupted.\n")
        return 130
    except FireworksError as exc:
        sys.stderr.write(f"{exc}\n")
        return 1


if __name__ == "__main__":
    raise SystemExit(main())
